  const ratioVisual=(value,total,label)=>`<div class="aud-feed-visual aud-viz aud-viz-ratio" role="img" aria-label="${value} of ${total} ${esc(label)}"><div class="aud-viz-title">${esc(label)}</div><div class="aud-viz-dots">${Array.from({length:total},(_,i)=>`<span class="${i<value?'is-filled':''}"></span>`).join('')}</div><small>${value} of ${total} sampled answers</small></div>`;
  const ga4Visual=(value,total,label,detail)=>`<div class="aud-feed-visual aud-viz aud-viz-share" role="img" aria-label="${value.toLocaleString()} of ${total.toLocaleString()} ${esc(label)}"><div class="aud-viz-title">${esc(label)}</div><div class="aud-viz-shareline"><strong>${value.toLocaleString()}</strong><span>${esc(detail)}</span></div><progress max="${total}" value="${value}">${value} of ${total}</progress><div class="aud-viz-scale"><span>${value.toLocaleString()}</span><span>${total.toLocaleString()} total</span></div></div>`;
