  const referralView=()=>`<section class="aeo-ga4-report" id="aeo-ai-traffic"><div class="aud-section-head"><div><h2>AI Traffic</h2><p>Human referrals in a sample GA4 export · Oct 4–Nov 2, 2026</p></div><span>Measured referrals</span></div><div class="aeo-traffic-readiness"><article><small>AI AGENT REQUESTS</small><strong>Logs needed</strong><p>Connect CDN or server logs to classify verified answer agents, indexing bots, and training crawlers.</p></article><article><small>ACCOUNTS ARRIVING FROM AI</small><strong>Identity needed</strong><p>Join eligible web visits to account IDs before showing target accounts or buying groups here.</p></article></div><div class="aeo-metrics"><div><strong>4,606</strong><span>reported sessions</span></div><div><strong>26</strong><span>key events</span></div><div><strong>3,482</strong>${engineLabel('ChatGPT / OpenAI')}</div></div><div class="aud-table-scroll"><table class="aud-table"><thead><tr><th>Answer engine</th><th>GA4 source values</th><th>Sessions</th><th>Engaged sessions</th><th>Key events</th></tr></thead><tbody>${referralEngines.map(row=>`<tr>${row.map((value,index)=>`<${index?'td':'th scope="row"'}>${index?esc(value):engineLabel(value)}</${index?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><details class="aeo-ga4-pages"><summary>Top landing pages · 25 of 1,155</summary><div class="aud-table-scroll"><table class="aud-table aeo-landing-table"><thead><tr><th>Landing page</th><th>Sessions</th><th>Engaged sessions</th></tr></thead><tbody>${landingPages.map(row=>`<tr><th scope="row">${esc(row[0])}</th><td>${row[1]}</td><td>${row[2]}</td></tr>`).join('')}</tbody></table></div></details><p class="aud-source">The five engine rows add to 4,603 sessions, three fewer than the supplied 4,606 total. This is session-source referral traffic, not citations or brand mentions. Direct visits may hide additional answer-engine traffic. These GA4 rows do not identify AI crawler requests or buying-group members.</p></section>`;
