    if(false){const decisions=[signals[2],signals[0],signals[1],signals[4]];root.innerHTML=`${tabs}<div class="aud-section-head"><div><h2>${decisions.length} decisions for Acme Co</h2><p>Choose a next step from the illustrative answer evidence, then send the brief to a content owner for review.</p></div><span>${decisions.length} to review</span></div><div class="aud-feed">${decisions.map(signal=>feedRow({...signal,id:`decision-${signal.id}`},'decision')).join('')}</div><p class="aud-source">These are proposed decisions from 12 illustrative answer records. Saving creates a browser-local brief; it does not publish content, contact a third party, or launch a campaign.</p>`;}
